-- 559: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 6 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_559_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_559_guard;
INSERT INTO _migration_559_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_021' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following best explains how the media contribute to the national development of Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They educate the public on health, agriculture and civic matters and expose wrongdoing","B. They replace the formal school system entirely","C. They collect taxes on behalf of the government","D. They appoint ministers and Members of Parliament"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Radio, television, newspapers and digital platforms carry health campaigns, agricultural extension advice and civic education in local languages, while investigative reporting exposes corruption — all of which support development. (Schools, tax collection and appointments are the work of the education system, the Ghana Revenue Authority and constitutional office holders, not the media.) Therefore the correct answer is A: They educate the public on health, agriculture and civic matters and expose wrongdoing.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_021' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_559_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_022' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The deliberate creation and spread of false information through the media in order to deceive the public is known as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Misinformation","B. Disinformation","C. Sensationalism","D. Censorship"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Disinformation is false information spread with the intent to deceive; misinformation is false information shared without that intent — the key distinction examiners look for. Sensationalism is exaggerating true stories to attract attention, and censorship is the suppression of information by authority. Therefore the correct answer is B: Disinformation.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_022' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_559_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_023' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A journalist who reports only the viewpoint of one political party in a contested election story violates the media ethic of...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Confidentiality of sources","B. Copyright protection","C. Balance and fairness","D. Freedom of the press"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Professional ethics require journalists to give all sides of a contested story a fair hearing so the public can judge for itself. Confidentiality of sources protects informants, copyright protects creative work, and press freedom protects the journalist — none of them addresses one-sided reporting. Therefore the correct answer is C: Balance and fairness.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_023' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_559_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_024' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a negative effect of media misuse on national development?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Health campaigns on radio improve public hygiene","B. Coverage of budgets keeps citizens informed","C. Advertising creates markets for local businesses","D. The spread of fake news can incite panic, hatred and social conflict"]' AND q.correct_answer IS 'D' AND q.explanation IS 'When media houses or users publish unverified or fabricated stories, the resulting panic and inter-group hostility can destabilize communities and slow development. The other three options are positive developmental roles of the media, so they cannot be answers to a question about negative effects. Therefore the correct answer is D: The spread of fake news can incite panic, hatred and social conflict.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_024' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_021', 'topic_wassce_p2_soc_med', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following best explains how the media contribute to the national development of Ghana?', 'multiple_choice', NULL, '["A. They educate the public on health, agriculture and civic matters and expose wrongdoing","B. They replace the formal school system entirely","C. They collect taxes on behalf of the government","D. They appoint ministers and Members of Parliament"]', 'A', 'Radio, television, newspapers and digital platforms carry health campaigns, agricultural extension advice and civic education in local languages, while investigative reporting exposes corruption — all of which support development. (Schools, tax collection and appointments are the work of the education system, the Ghana Revenue Authority and constitutional office holders, not the media.) Therefore the correct answer is A: They educate the public on health, agriculture and civic matters and expose wrongdoing.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_022', 'topic_wassce_p2_soc_med', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'The deliberate creation and spread of false information through the media in order to deceive the public is known as...', 'multiple_choice', NULL, '["A. Misinformation","B. Disinformation","C. Sensationalism","D. Censorship"]', 'B', 'Disinformation is false information spread with the intent to deceive; misinformation is false information shared without that intent — the key distinction examiners look for. Sensationalism is exaggerating true stories to attract attention, and censorship is the suppression of information by authority. Therefore the correct answer is B: Disinformation.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_023', 'topic_wassce_p2_soc_med', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'A journalist who reports only the viewpoint of one political party in a contested election story violates the media ethic of...', 'multiple_choice', NULL, '["A. Confidentiality of sources","B. Copyright protection","C. Balance and fairness","D. Freedom of the press"]', 'C', 'Professional ethics require journalists to give all sides of a contested story a fair hearing so the public can judge for itself. Confidentiality of sources protects informants, copyright protects creative work, and press freedom protects the journalist — none of them addresses one-sided reporting. Therefore the correct answer is C: Balance and fairness.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_024', 'topic_wassce_p2_soc_med', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a negative effect of media misuse on national development?', 'multiple_choice', NULL, '["A. Health campaigns on radio improve public hygiene","B. Coverage of budgets keeps citizens informed","C. Advertising creates markets for local businesses","D. The spread of fake news can incite panic, hatred and social conflict"]', 'D', 'When media houses or users publish unverified or fabricated stories, the resulting panic and inter-group hostility can destabilize communities and slow development. The other three options are positive developmental roles of the media, so they cannot be answers to a question about negative effects. Therefore the correct answer is D: The spread of fake news can incite panic, hatred and social conflict.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-social-studies-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_was_soc_s3_021', 'q_was_soc_s3_022', 'q_was_soc_s3_023', 'q_was_soc_s3_024');
